import React, { useState } from "react";

function Leaderboard() {
  const [usernamesInput, setUsernamesInput] = useState("");
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleFetch = async () => {
    const usernames = usernamesInput
      .split(",")
      .map(name => name.trim())
      .filter(name => name !== "");

    if (usernames.length === 0) return;

    setLoading(true);
    const results = await Promise.all(
      usernames.map(async (username) => {
        const query = {
          query: `
            query getUserProfile($username: String!) {
              matchedUser(username: $username) {
                username
                submitStats: submitStatsGlobal {
                  acSubmissionNum {
                    difficulty
                    count
                  }
                }
              }
              userContestRanking(username: $username) {
                rating
              }
            }
          `,
          variables: { username },
        };

        try {
          const res = await fetch("http://localhost:4000/api/leetcode", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(query),
          });

          const json = await res.json();
          const user = json.data.matchedUser;
          const rating = json.data.userContestRanking?.rating || "N/A";
          const problemsSolved = user?.submitStats?.acSubmissionNum?.find(x => x.difficulty === "All")?.count || 0;

          return {
            name: username,
            problemsSolved,
            contestRating: rating,
          };
        } catch (error) {
          return { name: username, problemsSolved: 0, contestRating: "Error" };
        }
      })
    );

    const sorted = results.sort((a, b) => b.problemsSolved - a.problemsSolved);
    setData(sorted);
    setLoading(false);
  };

  return (
    <div className="bg-white rounded-2xl shadow p-4 max-w-3xl mx-auto">
      <h2 className="text-xl font-bold mb-4">LeetCode Leaderboard</h2>
      <div className="mb-4">
        <input
          type="text"
          placeholder="Enter usernames separated by comma"
          value={usernamesInput}
          onChange={(e) => setUsernamesInput(e.target.value)}
          className="border p-2 rounded w-full"
        />
        <button
          onClick={handleFetch}
          className="mt-2 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
        >
          Generate Leaderboard
        </button>
      </div>

      {loading && <p className="text-center text-lg">Loading...</p>}

      {data.length > 0 && (
        <table className="min-w-full table-auto">
          <thead>
            <tr className="bg-blue-100">
              <th className="px-4 py-2 text-left">Rank</th>
              <th className="px-4 py-2 text-left">Name</th>
              <th className="px-4 py-2 text-left">Problems Solved</th>
              <th className="px-4 py-2 text-left">Rating</th>
            </tr>
          </thead>
          <tbody>
            {data.map((user, index) => (
              <tr key={index} className="border-b hover:bg-gray-50">
                <td className="px-4 py-2">{index + 1}</td>
                <td className="px-4 py-2 font-medium">{user.name}</td>
                <td className="px-4 py-2">{user.problemsSolved}</td>
                <td className="px-4 py-2">{user.contestRating}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default Leaderboard;
